请对以下 case 进行三维加权评分。

=== case_id ===
Case-11-fitness-014

=== 用户原始指令 (query.txt) ===
我想要夜跑用的卡片,黑色舞台背景那种,上面用语义图标(月亮、跑鞋那种),左右分区左边今日天气加跑步建议,右边是可勾选的动作项(已热身、已带水),勾选状态要能双向绑定,渐变用夜晚星空的感觉,下面纵向重复排几段"20:00-21:00 夜跑"这种日程,点卡片跳运动健康App,天气信息拉真实的。

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "我想要夜跑用的卡片,黑色舞台背景那种,上面用语义图标(月亮、跑鞋那种),左右分区左边今日天气加跑步建议,右边是可勾选的动作项(已热身、已带水),勾选状态要能双向绑定,渐变用夜晚星空的感觉,下面纵向重复排几段\"20:00-21:00 夜跑\"这种日程,点卡片跳运动健康App,天气信息拉真实的。",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "huaweischeme://healthapp/home/sport?sportType=2"
      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "weather": {
        "location": {
          "districtName": {
            "type": "string",
            "description": "实际查询成功的区县名称",
            "sampleValue": "当前位置"
          }
        },
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "当前温度展示文本",
            "sampleValue": "24°C"
          },
          "condition": {
            "type": "string",
            "description": "当前天气现象",
            "sampleValue": "多云"
          },
          "airQuality": {
            "type": "string",
            "description": "当前空气质量等级",
            "sampleValue": "良"
          },
          "windDirection": {
            "type": "string",
            "description": "当前风向",
            "sampleValue": "东北风"
          },
          "windLevel": {
            "type": "integer",
            "description": "当前风力等级",
            "sampleValue": 2
          }
        },
        "updatedAt": {
          "type": "string",
          "description": "天气查询更新时间",
          "sampleValue": "19:30"
        }
      }
    },
    "ui": {
      "assets": {
        "moonIcon": {
          "type": "string",
          "description": "月亮语义图标素材路径",
          "sampleValue": "resources/base/media/moon_circle_fill.svg"
        },
        "runIcon": {
          "type": "string",
          "description": "夜跑语义图标素材路径",
          "sampleValue": "resources/base/media/icon_run.png"
        }
      },
      "runAdvice": {
        "type": "string",
        "description": "结合当前天气给出的夜跑短建议",
        "sampleValue": "风小空气良，适合轻松跑"
      },
      "checklist": {
        "warmedUp": {
          "type": "boolean",
          "description": "已热身勾选状态",
          "sampleValue": false
        },
        "waterReady": {
          "type": "boolean",
          "description": "已带水勾选状态",
          "sampleValue": true
        }
      },
      "schedule": [
        {
          "displayText": {
            "type": "string",
            "description": "第一段夜跑日程展示文本",
            "sampleValue": "20:00-21:00 夜跑"
          }
        },
        {
          "displayText": {
            "type": "string",
            "description": "第二段夜跑日程展示文本",
            "sampleValue": "21:00-21:10 拉伸"
          }
        }
      ]
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/moon_circle_fill.svg",
      "description": "月亮圆形实心图标，适合表达夜跑、夜间模式或晚间场景。",
      "bindTo": "/ui/assets/moonIcon"
    },
    {
      "src": "resources/base/media/icon_run.png",
      "description": "运动跑步图标，适合表达夜跑、跑步计划或运动健康入口。",
      "bindTo": "/ui/assets/runIcon"
    }
  ]
}

